let csrf = "";
let moduleCache = [];
const $ = selector => document.querySelector(selector);
const api = async (path, options = {}) => {
  const response = await fetch(path, { ...options, headers: { "Content-Type": "application/json", ...(options.method && options.method !== "GET" ? { "x-nso-csrf": csrf } : {}), ...(options.headers || {}) } });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || "Có lỗi xảy ra.");
  return data;
};
const esc = value => String(value ?? "").replace(/[&<>'"]/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;" }[c]));
const tag = value => `<span class="tag ${["offline","failed","denied"].includes(String(value).toLowerCase()) ? "fail" : ["warning","pending"].includes(String(value).toLowerCase()) ? "warn" : ""}">${esc(value)}</span>`;
const itemThumb = (icon, label = "Vật phẩm", itemId = null) => { const sprite = Number(icon); const source = Number.isInteger(sprite) && sprite >= 0 ? `/api/item-icon?icon=${sprite}` : Number.isInteger(Number(itemId)) && Number(itemId) >= 0 ? `/api/item-icon?itemId=${Number(itemId)}` : ""; const fallback = Number.isInteger(sprite) && sprite >= 0 ? `#${sprite}` : itemId === null ? "?" : `#${itemId}`; return `<span class="item-thumb" title="${esc(label)}"><img ${source ? `src="${source}"` : "hidden"} alt="${esc(label)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false" /><span class="item-thumb-fallback"${source ? " hidden" : ""}>${esc(fallback)}</span></span>`; };
const mobThumb = (mobId, label = "Quái") => { const id = Number(mobId); const source = Number.isInteger(id) && id >= 0 ? `/api/monster-icon?id=${id}` : ""; const fallback = Number.isInteger(id) && id >= 0 ? `#${id}` : "?"; return `<span class="item-thumb mob-thumb" title="${esc(label)}"><img ${source ? `src="${source}"` : "hidden"} alt="${esc(label)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false" /><span class="item-thumb-fallback"${source ? " hidden" : ""}>${esc(fallback)}</span></span>`; };

function renderNav() {
  const byGroup = moduleCache.reduce((all, module) => ({ ...all, [module.group]: [...(all[module.group] || []), module] }), {});
  $("#module-nav").innerHTML = Object.entries(byGroup).map(([group, modules]) => `<div class="nav-group">${esc(group)}</div>${modules.map(module => `<button class="nav-item ${module.id === "dashboard" ? "active" : ""}" data-module="${module.id}"><span class="nav-icon">◈</span>${esc(module.label)}</button>`).join("")}`).join("");
  document.querySelectorAll(".nav-item").forEach(button => button.addEventListener("click", () => openModule(button.dataset.module)));
}

function setStatus(dbOnline, gamePortOpen) {
  const healthy = dbOnline && gamePortOpen;
  $("#status-dot").style.background = healthy ? "#4ddfca" : "#fa7070";
  $("#status-text").textContent = healthy ? "Local stack healthy" : "Cần kiểm tra local stack";
}

async function dashboard() {
  const data = await api("/api/dashboard");
  setStatus(data.dbOnline, data.gamePortOpen);
  $("#content").innerHTML = `
    <section class="grid metric-grid">
      <article class="card"><div class="metric-label">Game TCP 14444</div><div class="metric-value">${data.gamePortOpen ? "OPEN" : "CLOSED"}</div><div class="metric-hint">Liveness local socket</div></article>
      <article class="card"><div class="metric-label">MariaDB local</div><div class="metric-value">${data.dbOnline ? "READY" : "OFFLINE"}</div><div class="metric-hint">127.0.0.1:3306</div></article>
      <article class="card"><div class="metric-label">Người chơi online</div><div class="metric-value">${data.onlinePlayers}</div><div class="metric-hint">Từ cột players.online</div></article>
      <article class="card"><div class="metric-label">Tổng tài khoản</div><div class="metric-value">${data.totalAccounts}</div><div class="metric-hint">${data.totalPlayers} nhân vật</div></article>
    </section>
    ${data.alerts?.length ? `<section class="card alert-banner"><div class="section-title"><h3>${data.alerts.length} cảnh báo cần chú ý</h3><button class="ghost" data-open="incidents">Mở sự cố</button></div>${data.alerts.map(alert => `<p>${tag(alert.severity)} ${esc(alert.message)}</p>`).join("")}</section>` : ""}
    <section class="split"><article class="card"><div class="section-title"><h3>Audit gần đây</h3><button class="ghost" data-open="audit">Mở đầy đủ</button></div>${renderAudit(data.audit)}</article><article class="card"><div class="section-title"><h3>Trạng thái vận hành</h3></div><p class="muted">Panel chạy offline cùng máy server. MySQL không được public; mọi write được thực hiện bởi backend local qua allowlist và audit SQL.</p><div class="module-grid">${data.modules.slice(0,6).map(module => `<button class="module-card" data-open="${module.id}"><h4>${esc(module.label)}</h4><p>${esc(module.description)}</p></button>`).join("")}</div></article></section>`;
  document.querySelectorAll("[data-open]").forEach(button => button.addEventListener("click", () => openModule(button.dataset.open)));
}

function renderAudit(rows) {
  if (!rows?.length) return `<div class="empty">Chưa có thao tác quản trị nào được ghi nhận.</div>`;
  return `<div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Actor</th><th>Thao tác</th><th>Kết quả</th></tr></thead><tbody>${rows.map(row => `<tr><td>${esc(new Date(row.created_at).toLocaleString())}</td><td>${esc(row.actor_username || "System")}</td><td>${esc(row.module_name)} / ${esc(row.action_name)}</td><td>${tag(row.outcome)}</td></tr>`).join("")}</tbody></table></div>`;
}

async function playerModule() {
  $("#content").innerHTML = hero("Người chơi", "Tìm kiếm từ bảng players/users. Chỉnh chỉ số và hành trang chỉ mở khi nhân vật offline, có snapshot trước/sau và audit.") + `<div class="toolbar"><label>Tìm nhân vật hoặc username<input id="player-query" placeholder="Ví dụ: ninja01" /></label><button id="player-search" class="primary">Tìm kiếm</button></div><div id="player-results" class="empty">Nhập tên để tìm tối đa 50 kết quả.</div>`;
  $("#player-search").onclick = async () => { try { const { rows } = await api(`/api/players?q=${encodeURIComponent($("#player-query").value)}`); $("#player-results").innerHTML = table(rows, ["id","name","username","online","xu","yen","luong","coin","map"], true, row => `<button class="ghost" data-player-state="${row.id}">Chỉnh nhân vật</button>`); document.querySelectorAll("[data-player-state]").forEach(button => button.onclick = () => playerStateModule(Number(button.dataset.playerState))); } catch (e) { showError(e); } };
}

function parseJson(value, fallback) { try { const parsed = JSON.parse(value || ""); return parsed ?? fallback; } catch { return fallback; } }
function parseArrayStrict(value) { try { const parsed = JSON.parse(value || "[]"); return Array.isArray(parsed) ? parsed : null; } catch { return null; } }
function cloneJson(value) { return JSON.parse(JSON.stringify(value)); }
function dateTimeLocal(value) { const time = Number(value); if (!Number.isSafeInteger(time) || time <= 0) return ""; const date = new Date(time); return Number.isNaN(date.getTime()) ? "" : new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16); }
function inventoryTemplate(item, catalog) { return catalog.find(entry => Number(entry.id) === Number(item.id)) || null; }
function inventoryTemplateName(item, catalog) { const template = inventoryTemplate(item, catalog); return template ? `${template.name} · Type ${template.type}` : `Template #${item.id}`; }
function inventoryNextIndex(items) { const used = new Set(items.map(item => Number(item.index))); let index = 0; while (used.has(index)) index += 1; return index; }
function inventoryOptionRows(item, optionCatalog, section, index) { const options = Array.isArray(item.options) ? item.options : []; return options.map((option, optionIndex) => `<div class="inventory-option-row" data-inventory-option data-section="${section}" data-index="${index}" data-option-index="${optionIndex}"><select data-option-id>${optionCatalog.map(entry => `<option value="${entry.id}" ${Number(entry.id) === Number(option[0]) ? "selected" : ""}>#${entry.id} · ${esc(entry.name)}</option>`).join("")}</select><input data-option-value inputmode="numeric" value="${esc(option[1])}" aria-label="Giá trị option" /><button class="ghost" type="button" data-inventory-option-remove data-section="${section}" data-index="${index}" data-option-index="${optionIndex}">Bỏ</button></div>`).join("") || `<p class="muted inventory-none">Chưa có option chỉ số.</p>`; }
function inventoryItemCard(item, catalog, optionCatalog, section, index) { const template = inventoryTemplate(item, catalog); return `<article class="inventory-item" data-inventory-item data-section="${section}" data-index="${index}"><div class="inventory-item-head"><div class="item-label">${itemThumb(template?.icon, template?.name || `Item #${item.id}`, item.id)}<div><strong>Ô ${esc(item.index ?? index)} · ${esc(inventoryTemplateName(item, catalog))}</strong><small class="muted">ID ${esc(item.id)}</small></div></div><div class="inventory-item-actions"><button class="ghost" type="button" data-inventory-pick data-section="${section}" data-index="${index}">Đổi item</button><button class="ghost" type="button" data-inventory-remove data-section="${section}" data-index="${index}">Xóa</button></div></div><div class="inventory-item-grid"><label>Vị trí ô<input data-inventory-field="index" inputmode="numeric" value="${esc(item.index ?? index)}" /></label><label>Số lượng<input data-inventory-field="quantity" inputmode="numeric" value="${esc(item.quantity ?? 1)}" /></label><label>Khóa<select data-inventory-field="isLock"><option value="false" ${item.isLock ? "" : "selected"}>Không khóa</option><option value="true" ${item.isLock ? "selected" : ""}>Khóa</option></select></label><label>System<input data-inventory-field="sys" inputmode="numeric" value="${esc(item.sys ?? 0)}" /></label><label>Upgrade<input data-inventory-field="upgrade" inputmode="numeric" value="${esc(item.upgrade ?? 0)}" /></label><label>Yên item<input data-inventory-field="yen" inputmode="numeric" value="${esc(item.yen ?? 0)}" /></label><label class="inventory-expire">Hạn dùng <small>Để trống = vĩnh viễn</small><input data-inventory-field="expire" type="datetime-local" value="${dateTimeLocal(item.expire)}" /></label></div><details class="inventory-options"><summary>Option chỉ số (${Array.isArray(item.options) ? item.options.length : 0})</summary><div class="inventory-option-list">${inventoryOptionRows(item, optionCatalog, section, index)}</div><button class="ghost" type="button" data-inventory-option-add data-section="${section}" data-index="${index}">Thêm option</button></details></article>`; }
function inventorySectionCard(section, title, items, capacity, catalog, optionCatalog) { return `<article class="inventory-section"><div class="inventory-section-head"><div><h4>${title}</h4><p class="muted">${items.length}/${capacity} slot</p></div><button class="ghost" type="button" data-inventory-add data-section="${section}">Thêm vật phẩm</button></div><div class="inventory-items">${items.length ? items.map((item, index) => inventoryItemCard(item, catalog, optionCatalog, section, index)).join("") : `<div class="inventory-empty">Chưa có vật phẩm trong ${title.toLowerCase()}.</div>`}</div></article>`; }
function readVisualInventory(base) { const draft = cloneJson(base); document.querySelectorAll("[data-inventory-item]").forEach(node => { const section = node.dataset.section; const index = Number(node.dataset.index); const item = draft[section]?.[index]; if (!item) return; node.querySelectorAll("[data-inventory-field]").forEach(input => { const field = input.dataset.inventoryField; if (field === "isLock") item.isLock = input.value === "true"; else if (field === "expire") { const value = input.value ? new Date(input.value).getTime() : -1; item.expire = Number.isSafeInteger(value) ? value : -1; } else item[field] = Number(input.value); }); item.options = [...node.querySelectorAll("[data-inventory-option]")].map(option => [Number(option.querySelector("[data-option-id]").value), Number(option.querySelector("[data-option-value]").value)]); }); return draft; }
function defaultInventoryItem(id, items) { return { id:Number(id), expire:-1, index:inventoryNextIndex(items), isLock:false, yen:0, sys:0, upgrade:0, quantity:1, options:[] }; }

async function playerStateModule(playerId, state = {}) {
  const { row, editableStats, inventoryEditable, inventoryCatalog = [], optionCatalog = [] } = await api(`/api/player-state?playerId=${encodeURIComponent(playerId)}`);
  if (!row) { $("#content").innerHTML = `<div class="empty">Không tìm thấy nhân vật.</div>`; return; }
  const offline = Number(row.online) === 0;
  const parsedPotential = parseArrayStrict(row.potential || "[15,5,5,5]");
  const potential = Array.isArray(parsedPotential) && parsedPotential.length === 4 ? parsedPotential : null;
  const rawInventory = Object.fromEntries(["bag", "box", "equiped", "fashion"].map(section => [section, parseArrayStrict(row[section]) ]));
  const malformedSections = Object.entries(rawInventory).filter(([, value]) => value === null).map(([section]) => section);
  const inventory = state.inventory ? cloneJson(state.inventory) : rawInventory;
  const editableInventory = inventoryEditable && !malformedSections.length;
  const statField = (field, label, value, hint = "") => editableStats.includes(field) ? `<label>${esc(label)}<input name="${field}" value="${esc(value ?? "")}" inputmode="numeric" ${offline ? "" : "disabled"} />${hint ? `<small class="muted">${esc(hint)}</small>` : ""}</label>` : "";
  const inventoryPicker = state.picker || { section:"bag", index:null };
  const pickerTarget = inventoryPicker.index === null ? `Thêm vào ${inventoryPicker.section}` : `Đổi item tại ${inventoryPicker.section} / dòng ${Number(inventoryPicker.index) + 1}`;
  const inventoryUi = editableInventory ? `<section class="card inventory-control" style="margin-top:16px"><div class="section-title"><div><h3>Hành trang trực quan</h3><p class="muted">Chọn item từ catalog, sau đó chỉnh từng ô. Panel tự chuẩn hóa dữ liệu theo contract game khi lưu.</p></div><span class="tag">Offline only</span></div><form id="player-inventory-form"><div class="inventory-section-grid">${inventorySectionCard("bag", "Túi đồ", inventory.bag, Math.min(Number(row.numberCellBag) || 200, 200), inventoryCatalog, optionCatalog)}${inventorySectionCard("box", "Rương", inventory.box, Math.min(Number(row.numberCellBox) || 200, 200), inventoryCatalog, optionCatalog)}${inventorySectionCard("equiped", "Trang bị", inventory.equiped, 16, inventoryCatalog, optionCatalog)}${inventorySectionCard("fashion", "Thời trang", inventory.fashion, 16, inventoryCatalog, optionCatalog)}</div><section class="inventory-picker"><div class="section-title"><div><h4>Chọn vật phẩm từ catalog</h4><p class="muted">Đích hiện tại: ${esc(pickerTarget)}</p></div></div><div class="toolbar"><label>Tìm ID hoặc tên item<input id="inventory-item-query" placeholder="Ví dụ: lồng đèn" /></label><button id="inventory-item-search" type="button" class="ghost">Tìm item</button></div><div id="inventory-item-results" class="inventory-empty">Danh mục đầu có ${inventoryCatalog.length} item. Tìm để chọn chính xác template.</div></section><div class="actions"><button class="primary" type="submit" ${offline ? "" : "disabled"}>Lưu hành trang có xác nhận</button></div></form></section>` : `<section class="card" style="margin-top:16px"><p class="error">${malformedSections.length ? `Không thể mở editor trực quan vì dữ liệu cũ lỗi ở: ${malformedSections.join(", ")}. Không có dữ liệu nào bị tự động thay đổi.` : "Schema game hiện tại không có đủ cột bag/box/equiped/fashion để mở hành trang."}</p></section>`;
  $("#content").innerHTML = hero(`Chỉnh nhân vật #${row.id}`, "Chỉ ghi SQL khi nhân vật offline. Mỗi lần lưu tạo snapshot trước/sau; Java nạp state khi người chơi đăng nhập lại.") + `<section class="card"><h3>${esc(row.name)} ${tag(offline ? "offline" : "online")}</h3><p class="muted">${offline ? "Dữ liệu có thể chỉnh. Yêu cầu người chơi logout hoàn toàn trước khi lưu." : "Bị khóa vì nhân vật đang online, tránh ghi đè state trong bộ nhớ Java."}</p></section><section class="card" style="margin-top:16px"><div class="section-title"><h3>Chỉ số nhân vật</h3><span class="muted">Nhập số trực tiếp, không cần mã kỹ thuật</span></div><form id="player-stats-form" class="form-grid">${statField("point", "Điểm tiềm năng còn lại", row.point)}${statField("spoint", "Điểm kỹ năng còn lại", row.spoint)}${statField("exp", "EXP (level do Java suy ra)", parseJson(row.data, {}).exp ?? 0, "Không nhập level trực tiếp.")}${statField("numberCellBag", "Số ô túi", row.numberCellBag)}${statField("numberCellBox", "Số ô rương", row.numberCellBox)}${potential ? `<fieldset class="full potential-editor"><legend>Tiềm năng</legend><label>HP<input name="potentialHp" inputmode="numeric" value="${esc(potential[0])}" ${offline ? "" : "disabled"} /></label><label>MP<input name="potentialMp" inputmode="numeric" value="${esc(potential[1])}" ${offline ? "" : "disabled"} /></label><label>Sát thương<input name="potentialDamage" inputmode="numeric" value="${esc(potential[2])}" ${offline ? "" : "disabled"} /></label><label>Phòng thủ<input name="potentialDefense" inputmode="numeric" value="${esc(potential[3])}" ${offline ? "" : "disabled"} /></label></fieldset>` : `<p class="full error">Potential cũ không đúng 4 giá trị; editor giữ khóa để tránh ghi đè dữ liệu lỗi.</p>`}<div class="full"><button class="primary" ${offline && potential ? "" : "disabled"}>Lưu chỉ số có xác nhận</button></div></form></section>${inventoryUi}`;
  $("#player-stats-form").onsubmit = event => { event.preventDefault(); const stats = Object.fromEntries(new FormData(event.currentTarget)); stats.potential = JSON.stringify([stats.potentialHp, stats.potentialMp, stats.potentialDamage, stats.potentialDefense]); delete stats.potentialHp; delete stats.potentialMp; delete stats.potentialDamage; delete stats.potentialDefense; confirmAction("Lưu chỉ số nhân vật", `Nhập APPLY PLAYER STATS ${row.id}. Panel tạo snapshot trước/sau và Java cần nhân vật login lại để nhận state.`, async confirmation => { await api("/api/actions/player-stats-update", { method:"POST", body:JSON.stringify({ playerId:row.id, stats, confirmation }) }); await playerStateModule(row.id); }); };
  if (!editableInventory) return;
  const rerenderInventory = (nextInventory, picker = state.picker) => playerStateModule(row.id, { inventory:nextInventory, picker });
  document.querySelectorAll("[data-inventory-add]").forEach(button => button.onclick = () => rerenderInventory(readVisualInventory(inventory), { section:button.dataset.section, index:null }));
  document.querySelectorAll("[data-inventory-pick]").forEach(button => button.onclick = () => rerenderInventory(readVisualInventory(inventory), { section:button.dataset.section, index:Number(button.dataset.index) }));
  document.querySelectorAll("[data-inventory-remove]").forEach(button => button.onclick = () => { const draft = readVisualInventory(inventory); draft[button.dataset.section].splice(Number(button.dataset.index), 1); rerenderInventory(draft); });
  document.querySelectorAll("[data-inventory-option-add]").forEach(button => button.onclick = () => { const draft = readVisualInventory(inventory); const item = draft[button.dataset.section][Number(button.dataset.index)]; item.options = [...(item.options || []), [Number(optionCatalog[0]?.id || 0), 0]]; rerenderInventory(draft); });
  document.querySelectorAll("[data-inventory-option-remove]").forEach(button => button.onclick = () => { const draft = readVisualInventory(inventory); const item = draft[button.dataset.section][Number(button.dataset.index)]; item.options.splice(Number(button.dataset.optionIndex), 1); rerenderInventory(draft); });
  $("#inventory-item-search").onclick = async () => { try { const { rows } = await api(`/api/items?q=${encodeURIComponent($("#inventory-item-query").value)}&type=all&gender=all`); $("#inventory-item-results").innerHTML = rows.length ? table(rows, ["icon", "id", "name", "type", "gender", "level"], true, item => `<button class="ghost" data-inventory-choose-item="${item.id}">Chọn item này</button>`) : `<div class="inventory-empty">Không tìm thấy item phù hợp.</div>`; document.querySelectorAll("[data-inventory-choose-item]").forEach(button => button.onclick = () => { const draft = readVisualInventory(inventory); const id = Number(button.dataset.inventoryChooseItem); if (inventoryPicker.index === null) draft[inventoryPicker.section].push(defaultInventoryItem(id, draft[inventoryPicker.section])); else { const old = draft[inventoryPicker.section][inventoryPicker.index]; draft[inventoryPicker.section][inventoryPicker.index] = { ...defaultInventoryItem(id, draft[inventoryPicker.section]), index:old.index, isLock:old.isLock, quantity:old.quantity, sys:old.sys, upgrade:old.upgrade, yen:old.yen, expire:old.expire, options:old.options || [] }; } rerenderInventory(draft); }); } catch (error) { showError(error); } };
  $("#player-inventory-form").onsubmit = event => { event.preventDefault(); const draft = readVisualInventory(inventory); confirmAction("Lưu hành trang", `Nhập APPLY INVENTORY ${row.id}. Chỉ thực hiện khi nhân vật offline; panel tạo snapshot trước/sau.`, async confirmation => { await api("/api/actions/player-inventory-update", { method:"POST", body:JSON.stringify({ playerId:row.id, inventory:draft, confirmation }) }); await playerStateModule(row.id); }); };
}

async function accountModule() {
  $("#content").innerHTML = hero("Tài khoản & kiểm duyệt", "Tạo account game với bcrypt $2y$ tương thích Java; khoá/mở khoá và ban dùng users.status/ban_until. Mọi thao tác cần xác nhận và audit.") + `<section class="card" style="margin-top:16px"><div class="section-title"><h3>Tạo tài khoản game</h3></div><form id="account-create-form" class="form-grid"><label>Username (3-30; chữ, số hoặc _)<input name="username" minlength="3" maxlength="30" autocomplete="off" required /></label><label>Mật khẩu game (8-100)<input name="password" type="password" minlength="8" maxlength="100" autocomplete="new-password" required /></label><label>Xác nhận mật khẩu<input name="passwordConfirm" type="password" minlength="8" maxlength="100" autocomplete="new-password" required /></label><button class="primary">Tạo account có xác nhận</button></form></section><section class="card" style="margin-top:16px"><div class="toolbar"><label>Tìm username<input id="account-query" /></label><button id="account-search" class="primary">Tìm tài khoản</button></div><div id="account-results" class="empty">Chưa có kết quả.</div></section>`;
  $("#account-create-form").onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); const username = String(data.username).trim(); if (data.password !== data.passwordConfirm) { showError(new Error("Xác nhận mật khẩu chưa khớp.")); return; } confirmAction("Tạo tài khoản game", `Nhập CREATE ACCOUNT ${username} để tạo account. Mật khẩu không được ghi audit.`, async confirmation => { await api("/api/actions/account-create", { method:"POST", body:JSON.stringify({ username, password:data.password, confirmation }) }); event.currentTarget.reset(); await accountModule(); }); };
  $("#account-search").onclick = async () => { try { const { rows } = await api(`/api/accounts?q=${encodeURIComponent($("#account-query").value)}`); $("#account-results").innerHTML = table(rows, ["id","username","status","activated","online","luong","coin","ban_until"], true, row => `<button class="ghost" data-account="${row.id}">Trạng thái</button><button class="ghost" data-ban-account="${row.id}">Ban</button>`); document.querySelectorAll("[data-account]").forEach(btn => btn.onclick = () => accountStatus(btn.dataset.account)); document.querySelectorAll("[data-ban-account]").forEach(btn => btn.onclick = () => banAccount(btn.dataset.banAccount)); } catch (e) { showError(e); } };
}

async function shopModuleLegacy() { const [coinShop, npcShop] = await Promise.all([api("/api/shop"), api("/api/npc-shops")]); const storeOptions = npcShop.stores.map(store => `<option value="${store.id}">${esc(store.id)} — ${esc(store.name)}</option>`).join(""); $("#content").innerHTML = hero("Cửa hàng", "Quản lý shopcoin và store_data của shop NPC theo schema thực. Sau khi sửa, Java StoreManager cần reload/restart để đồng bộ cache.") + `<section class="card"><div class="section-title"><h3>Shopcoin</h3><span class="muted">shopcoin_tb1</span></div>${table(coinShop.rows, ["id","idItem","itemName","price","upgrade","system","options"], true, row => `<button class="ghost" data-shop="${row.id}">Chỉnh</button>`)}</section><section class="card" style="margin-top:16px"><div class="section-title"><h3>Shop NPC</h3><span class="muted">stores + store_data</span></div><p class="muted">Store type được Java StoreManager tải vào bộ nhớ. Danh sách NPC bên dưới chỉ để tham chiếu menu; mapping menu→store nằm trong mã Java.</p><form id="npc-store-create-form" class="toolbar"><label>Tên store mới<input name="name" maxlength="500" required /></label><button class="ghost">Tạo store</button></form><details><summary>Tham chiếu NPC (${npcShop.npcs.length})</summary>${table(npcShop.npcs,["id","name","head","body","leg","menu"])}</details></section><section class="card" style="margin-top:16px"><form id="npc-shop-item-form" class="form-grid"><input type="hidden" name="id" /><label>Store<select name="storeId" required>${storeOptions}</select></label><label>Item template ID<input name="itemId" inputmode="numeric" required /></label><label>System<input name="sys" value="0" inputmode="numeric" required /></label><label>Khóa<select name="lock"><option value="0">Không khóa</option><option value="1">Khóa</option></select></label><label>Coin<input name="coin" value="0" inputmode="numeric" required /></label><label>Lượng<input name="gold" value="0" inputmode="numeric" required /></label><label>Yên<input name="yen" value="0" inputmode="numeric" required /></label><label>Expire ms (-1 = vô hạn)<input name="expire" value="-1" inputmode="numeric" required /></label><label class="full">Options JSON array<textarea name="options" rows="2">[]</textarea></label><div class="full"><button class="primary" id="npc-shop-submit">Thêm hàng hóa NPC</button><button class="ghost" type="button" id="npc-shop-reset">Xóa form</button></div></form><div style="margin-top:16px">${table(npcShop.rows, ["id","store","store_name","item_id","item_name","sys","lock","coin","gold","yen","expire","options"], true, row => `<button class="ghost" data-npc-shop-edit="${row.id}">Nạp form</button><button class="ghost" data-npc-shop-delete="${row.id}">Xóa</button>`)}</div></section>`; document.querySelectorAll("[data-shop]").forEach(btn => btn.onclick = () => shopEdit(coinShop.rows.find(row => String(row.id) === btn.dataset.shop))); const npcForm = $("#npc-shop-item-form"); const resetNpcForm = () => { npcForm.reset(); npcForm.elements.id.value = ""; $("#npc-shop-submit").textContent = "Thêm hàng hóa NPC"; }; $("#npc-shop-reset").onclick = resetNpcForm; $("#npc-store-create-form").onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); confirmAction("Tạo store NPC", "Nhập CREATE NPC STORE để tạo store mới. Cần reload/restart Java để áp dụng.", async confirmation => { await api("/api/actions/store-create", { method:"POST", body:JSON.stringify({ ...data, confirmation }) }); await shopModule(); }); }; $("#npc-shop-item-form").onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); const id = data.id ? Number(data.id) : null; const action = id ? "Cập nhật hàng hóa NPC" : "Thêm hàng hóa NPC"; const phrase = id ? `APPLY NPC SHOP ITEM ${id}` : `ADD NPC SHOP ITEM ${data.storeId}`; confirmAction(action, `Nhập ${phrase}. Java StoreManager sẽ cần reload/restart để nhận dữ liệu mới.`, async confirmation => { await api(id ? "/api/actions/npc-shop-item-update" : "/api/actions/npc-shop-item-create", { method:"POST", body:JSON.stringify({ ...data, ...(id ? { id } : {}), confirmation }) }); await shopModule(); }); }; document.querySelectorAll("[data-npc-shop-edit]").forEach(button => button.onclick = () => { const row = npcShop.rows.find(item => String(item.id) === button.dataset.npcShopEdit); if (!row) return; Object.entries({ id:row.id, storeId:row.store, itemId:row.item_id, sys:row.sys, lock:row.lock, coin:row.coin, gold:row.gold, yen:row.yen, expire:row.expire, options:row.options || "[]" }).forEach(([name, value]) => { if (npcForm.elements[name]) npcForm.elements[name].value = value; }); $("#npc-shop-submit").textContent = `Cập nhật hàng #${row.id}`; npcForm.scrollIntoView({ behavior:"smooth", block:"center" }); }); document.querySelectorAll("[data-npc-shop-delete]").forEach(button => button.onclick = () => { const id = Number(button.dataset.npcShopDelete); confirmAction("Xóa hàng hóa NPC", `Nhập DELETE NPC SHOP ITEM ${id}. Thao tác có audit và cần reload/restart Java.`, async confirmation => { await api("/api/actions/npc-shop-item-delete", { method:"POST", body:JSON.stringify({ id, confirmation }) }); await shopModule(); }); }); }
function shopDateLocal(value) { return Number(value) > 0 ? dateTimeLocal(value) : ""; }
function shopOptionRows(options, optionCatalog) { return options.map((option, index) => `<div class="shop-option-row" data-shop-option data-index="${index}"><select data-shop-option-id>${optionCatalog.map(entry => `<option value="${entry.id}" ${Number(entry.id) === Number(option[0]) ? "selected" : ""}>#${entry.id} · ${esc(entry.name)}</option>`).join("")}</select><input data-shop-option-value inputmode="numeric" value="${esc(option[1])}" aria-label="Giá trị option" /><button class="ghost" type="button" data-shop-option-remove data-index="${index}">Bỏ</button></div>`).join("") || `<p class="muted inventory-none">Chưa có option chỉ số.</p>`; }
function shopPriceDraft(row) { const values = { coin:Number(row?.coin || 0), gold:Number(row?.gold || 0), yen:Number(row?.yen || 0) }; const populated = Object.entries(values).filter(([, value]) => value > 0); const [currency, value] = populated.length === 1 ? populated[0] : [populated.length > 1 ? "custom" : "coin", populated[0]?.[1] || 0]; return { priceMode:currency, priceValue:value, ...values }; }
function shopDraft(row, storeId) { const base = { id:"", storeId:String(storeId || ""), itemId:"", itemName:"Chưa chọn item", itemIcon:null, sys:"0", lock:"0", expire:"", options:[], ...shopPriceDraft(null) }; if (!row) return base; return { ...base, id:row.id, storeId:String(row.store), itemId:String(row.item_id), itemName:row.item_name || `Item #${row.item_id}`, itemIcon:row.item_icon, sys:String(row.sys), lock:String(row.lock), expire:shopDateLocal(row.expire), options:parseJson(row.options, []), ...shopPriceDraft(row) }; }
function shopCompactPrice(row) { const values = [["Coin", row.coin], ["Lượng", row.gold], ["Yên", row.yen]].filter(([, value]) => Number(value) > 0); return values.length ? values.map(([label, value]) => `${label} ${value}`).join(" + ") : "Miễn phí"; }
