async function maintenanceModule() { const data = await api("/api/maintenance"); $("#content").innerHTML = hero("Bảo trì", data.runtimeLimit) + `<section class="card"><form id="maintenance-form" class="form-grid"><label>Bắt đầu<input type="datetime-local" name="startsAt" required /></label><label>Kết thúc<input type="datetime-local" name="endsAt" required /></label><label class="full">Thông điệp/runbook<input name="message" maxlength="500" required /></label><button class="primary">Tạo maintenance draft</button></form></section><section style="margin-top:16px">${table(data.rows,["id","starts_at","ends_at","message","status","created_by","approved_by"],true,row => row.status === "draft" ? `<button class="ghost" data-maintenance-approve="${row.id}">Phê duyệt</button>` : tag(row.status))}</section>`; $("#maintenance-form").onsubmit = event => { event.preventDefault(); const payload = Object.fromEntries(new FormData(event.currentTarget)); confirmAction("Tạo maintenance draft", "Nhập CREATE MAINTENANCE DRAFT để tạo kế hoạch chưa tác động server.", async confirmation => { await api("/api/actions/maintenance-draft", { method:"POST", body:JSON.stringify({ ...payload, confirmation }) }); await maintenanceModule(); }); }; document.querySelectorAll("[data-maintenance-approve]").forEach(button => button.onclick = () => confirmAction("Phê duyệt maintenance", `Nhập APPROVE MAINTENANCE ${button.dataset.maintenanceApprove}. Thao tác này chỉ phê duyệt runbook, không dừng Java server.`, async confirmation => { await api("/api/actions/maintenance-approve", { method:"POST", body:JSON.stringify({ id:Number(button.dataset.maintenanceApprove), confirmation }) }); await maintenanceModule(); })); }
async function passwordModule() { $("#content").innerHTML = hero("Chế độ local-only", "Control Room không có tài khoản, mật khẩu, cookie session hoặc phân quyền người dùng.") + `<section class="card"><p class="muted">Panel được ép bind tại 127.0.0.1 trên chính thiết bị. Các thao tác ghi vẫn cần token CSRF local theo phiên chạy, mã xác nhận rõ ràng và được audit với actor <code>local-only</code>.</p><p class="muted">Không mở port panel hoặc MariaDB ra mạng LAN/Internet. Nếu cần thay đổi dữ liệu game, vẫn dùng confirmation phrase và bảo đảm nhân vật offline khi module yêu cầu.</p></section>`; }
async function optionsModule(kind) { const { rows } = await api("/api/options"); const isNotice = kind === "notices"; const selected = rows.filter(row => isNotice ? row.key === "notify" : row.key !== "notify"); $("#content").innerHTML = hero(isNotice ? "Thông báo" : "Tỷ lệ game", isNotice ? "Cập nhật options.notify mà game Java đọc. Nội dung thông báo cần được review trước khi phát hành." : "Cập nhật expserver hoặc levelnjtl theo option Java server tải khi khởi động.") + `<section class="grid">${selected.map(row => `<article class="card"><div class="section-title"><h3>${esc(row.key)}</h3><button class="ghost" data-option="${esc(row.key)}">Cập nhật</button></div><pre class="muted" style="white-space:pre-wrap;overflow:auto">${esc(row.value ?? "")}</pre></article>`).join("") || `<div class="empty">Chưa có option. Khi cập nhật, panel chỉ dùng key allowlist.</div>`}</section>`; document.querySelectorAll("[data-option]").forEach(button => button.onclick = () => optionEdit(button.dataset.option, rows.find(row => row.key === button.dataset.option)?.value || "")); }
async function backupsModule() { $("#content").innerHTML = hero("Sao lưu", "Tạo dump SQL local trong admin-panel/backups. File backup không được public web.") + `<section class="card" style="margin-top:16px"><p class="muted">Hãy đảm bảo máy còn dung lượng trống trước khi tạo backup.</p><button id="create-backup" class="primary">Tạo database backup</button></section>`; $("#create-backup").onclick = () => confirmAction("Tạo backup", "Nhập CREATE BACKUP để bắt đầu MariaDB dump local.", async confirmation => { const result = await api("/api/actions/backup", { method:"POST", body:JSON.stringify({ confirmation }) }); alert(`Đã tạo ${result.filename}`); }); }
async function jobsModule() { const { rows } = await api("/api/jobs"); $("#content").innerHTML = hero("Tác vụ định kỳ", "Tạo draft cron UTC sáu trường. Job mặc định disabled; chỉ admin có thể bật sau review.") + `<section class="card" style="margin-top:16px"><form id="job-form" class="form-grid"><label>Tên job<input name="name" required /></label><label>Loại job<select name="jobType"><option value="health_check">Health check</option><option value="daily_report">Daily report</option><option value="cleanup">Cleanup</option><option value="event_transition">Event transition</option><option value="maintenance_transition">Maintenance transition</option></select></label><label class="full">Cron 6-field UTC<input name="cronExpression" value="0 */5 * * * *" required /></label><button class="primary">Tạo draft có xác nhận</button></form></section><section style="margin-top:16px">${table(rows, ["id","name","job_type","cron_expression","enabled","last_run_at","last_result"], true, row => Number(row.enabled) ? tag("enabled") : `<button class="ghost" data-job-enable="${row.id}">Phê duyệt & bật</button>`)}</section>`; $("#job-form").onsubmit = event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); confirmAction("Tạo job draft", "Nhập CREATE JOB DRAFT để tạo cấu hình disabled và audit.", async confirmation => { await api("/api/actions/job-draft", { method:"POST", body:JSON.stringify({ ...data, confirmation }) }); await jobsModule(); }); }; document.querySelectorAll("[data-job-enable]").forEach(button => button.onclick = () => confirmAction("Bật job", `Nhập ENABLE JOB ${button.dataset.jobEnable} để phê duyệt và bật job.`, async confirmation => { await api("/api/actions/job-enable", { method:"POST", body:JSON.stringify({ id:Number(button.dataset.jobEnable), confirmation }) }); await jobsModule(); })); }

function hero(title, description) { return `<section class="card module-hero"><div><p class="eyebrow">OFFLINE SQL CONTROL</p><h3>${esc(title)}</h3><p>${esc(description)}</p></div><button class="ghost" id="back-dashboard">Quay về dashboard</button></section>`; }
function tableValue(row, col) { if (col === "icon" && row.mob_icon !== undefined) return mobThumb(row.mob_icon, row.name || `Quái #${row.mob_icon}`); if (["icon", "item_icon", "itemIcon"].includes(col)) return itemThumb(row[col], row.name || row.item_name || row.itemName || `Icon ${row[col]}`, row.idItem || row.item_id || row.id); if (col === "online") return tag(Number(row[col]) ? "online" : "offline"); return esc(typeof row[col] === "object" ? JSON.stringify(row[col]) : row[col]); }
function table(rows, columns, actions = false, action = () => "") { if (!rows.length) return `<div class="empty">Không có dữ liệu phù hợp.</div>`; return `<div class="table-wrap"><table><thead><tr>${columns.map(c => `<th>${esc(c)}</th>`).join("")}${actions ? "<th>Thao tác</th>" : ""}</tr></thead><tbody>${rows.map(row => `<tr>${columns.map(col => `<td>${tableValue(row, col)}</td>`).join("")}${actions ? `<td>${action(row)}</td>` : ""}</tr>`).join("")}</tbody></table></div>`; }
function showError(error) { $("#content").insertAdjacentHTML("afterbegin", `<div class="card"><strong class="error">${esc(error.message || error)}</strong></div>`); }
function confirmAction(title, prompt, callback) { const node = $("#confirm-template").content.cloneNode(true); const wrap = document.createElement("div"); wrap.append(node); const dialog = wrap.firstElementChild; const confirmButton = dialog.querySelector(".confirm"); const cancelButton = dialog.querySelector(".cancel"); dialog.querySelector("h3").textContent = title; dialog.querySelector("p").textContent = prompt; cancelButton.onclick = () => dialog.remove(); confirmButton.onclick = async () => { const code = dialog.querySelector("input").value; confirmButton.disabled = true; cancelButton.disabled = true; confirmButton.textContent = "Đang xử lý…"; dialog.setAttribute("aria-busy", "true"); try { await callback(code); dialog.remove(); } catch (e) { dialog.querySelector("p").textContent = e.message; confirmButton.disabled = false; cancelButton.disabled = false; confirmButton.textContent = "Thử lại"; dialog.removeAttribute("aria-busy"); } }; $("#content").append(dialog); dialog.querySelector("input").focus(); }
function accountStatus(id) { confirmAction("Đổi trạng thái", `Nhập APPLY ACCOUNT ${id} để mở thao tác. Sau đó chọn status trong trường nhập: 0=Deactivate, 1=Active, 2=Block.`, async confirmation => { const status = Number(prompt("Status mới (0, 1, hoặc 2):", "2")); await api("/api/actions/account-status", { method:"POST", body:JSON.stringify({ userId:Number(id), status, confirmation }) }); await accountModule(); }); }
function banAccount(id) { const banUntil = prompt("Thời hạn ban theo local time (YYYY-MM-DDTHH:MM), phải sau thời điểm hiện tại:", ""); if (banUntil === null) return; confirmAction("Ban tài khoản", `Nhập BAN ACCOUNT ${id}. Ban sẽ ghi users.status=2 và ban_until, có audit.`, async confirmation => { await api("/api/actions/account-ban", { method:"POST", body:JSON.stringify({ userId:Number(id), banUntil, confirmation }) }); await accountModule(); }); }
function shopEdit(row) { const price = prompt("Giá mới", row.price); if (price === null) return; confirmAction("Cập nhật shop", `Nhập APPLY SHOP ${row.id}. Thay đổi sẽ cần reload shop trong server Java để áp dụng.`, async confirmation => { await api("/api/actions/shop-update", { method:"POST", body:JSON.stringify({ id:row.id, price:Number(price), upgrade:row.upgrade, system:row.system, options:row.options || "[]", confirmation }) }); await shopModule(); }); }
function monsterEdit(row) { const hp = prompt("HP mới", row.hp); if (hp === null) return; confirmAction("Cập nhật monster", `Nhập APPLY MONSTER ${row.id}. Cần restart/reload game server để cache quái cập nhật.`, async confirmation => { await api("/api/actions/monster-update", { method:"POST", body:JSON.stringify({ ...row, hp:Number(hp), confirmation }) }); await bossModule(); }); }
function itemEdit(row) { const name = prompt("Tên item", row.name); if (name === null) return; const type = prompt("Type", row.type); if (type === null) return; const gender = prompt("Gender (-1/0/1/2)", row.gender); if (gender === null) return; const level = prompt("Level", row.level); if (level === null) return; const icon = prompt("Icon", row.icon); if (icon === null) return; const part = prompt("Part", row.part); if (part === null) return; const fashion = prompt("Fashion", row.fashion); if (fashion === null) return; const isUpToUp = prompt("Upgradable (0 hoặc 1)", row.isUpToUp); if (isUpToUp === null) return; const description = prompt("Mô tả", row.description); if (description === null) return; confirmAction("Cập nhật item", `Nhập APPLY ITEM ${row.id}. Thay đổi cần reload item cache.`, async confirmation => { await api("/api/actions/item-update", { method:"POST", body:JSON.stringify({ id:row.id, name, type:Number(type), gender:Number(gender), level:Number(level), icon:Number(icon), part:Number(part), fashion:Number(fashion), isUpToUp:Number(isUpToUp), description, confirmation }) }); await itemModule(); }); }
function optionEdit(key, currentValue) { const value = prompt(`Giá trị mới cho ${key}`, currentValue); if (value === null) return; confirmAction("Cập nhật option", `Nhập APPLY OPTION ${key}. Java server có thể cần reload/restart để nhận option mới.`, async confirmation => { await api("/api/actions/option-update", { method:"POST", body:JSON.stringify({ key, value, confirmation }) }); await optionsModule(key === "notify" ? "notices" : "rates"); }); }
async function moduleLanding(module) { $("#content").innerHTML = hero(module.label, module.description) + `<section class="module-grid">${modulesByGroup(module.group).map(item => `<article class="module-card"><p class="eyebrow">${esc(item.group)}</p><h4>${esc(item.label)}</h4><p>${esc(item.description)}</p></article>`).join("")}</section><div class="card" style="margin-top:16px"><h3>Safe SQL boundary</h3><p class="muted">Module này đã có registry quyền và audit boundary. Phần ghi dữ liệu sẽ chỉ được mở khi truy vấn allowlist tương ứng đã đối chiếu với SQLStatement.java, có validation và confirmation.</p></div>`; }
function modulesByGroup(group) { return moduleCache.filter(module => module.group === group); }
async function openModuleLegacy(id) { document.querySelectorAll(".nav-item").forEach(btn => btn.classList.toggle("active", btn.dataset.module === id)); const module = moduleCache.find(item => item.id === id); $("#page-title").textContent = module?.label || "Control Room"; document.querySelector(".sidebar")?.classList.remove("open"); $("#content").innerHTML = `<div class="loading" role="status" aria-live="polite">Đang tải mô-đun…</div>`; try { if (id === "dashboard" || id === "health") await dashboard(); else if (id === "players") await playerModule(); else if (id === "accounts" || id === "moderation") await accountModule(); else if (id === "inventory") await inventoryModule(); else if (id === "currency") await currencyModule(); else if (id === "custom-items") await itemModule(); else if (id === "rewards") await giftModule(); else if (id === "reward-campaigns") await rewardCampaignModule(); else if (id === "reward-history") await rewardHistoryModule(); else if (id === "shop") await shopModule(); else if (id === "events") await eventModule(); else if (id === "bosses") await bossModule(); else if (id === "rates") await optionsModule("rates"); else if (id === "notices") await optionsModule("notices"); else if (id === "maintenance") await maintenanceModule(); else if (id === "backups") await backupsModule(); else if (id === "leaderboards") await leaderboardModule(); else if (id === "analytics") await analyticsModule(); else if (id === "jobs") await jobsModule(); else if (id === "incidents") await incidentsModule(); else if (id === "audit" || id === "logs") await auditModule(); else if (id === "security") await passwordModule(); else await moduleLanding(module); $("#back-dashboard")?.addEventListener("click", () => openModuleLegacy("dashboard")); } catch (e) { $("#content").innerHTML = `<div class="empty">${esc(e.message || e)}</div>`; } }

async function boot() { try { const context = await api("/api/local/context"); csrf = context.csrf; $("#role-badge").textContent = "Local-only / không đăng nhập"; moduleCache = (await api("/api/modules")).modules; renderNav(); await openModule("dashboard"); } catch (e) { $("#content").innerHTML = `<div class="empty">${esc(e.message || e)}</div>`; } }
