    $("#inventory-result").innerHTML = `<section class="card"><div class="section-title"><div><h3>${esc(row.name)} #${esc(row.id)}</h3><p class="muted">${row.numberCellBag} ô túi / ${row.numberCellBox} ô rương · ${tag(Number(row.online) ? "online" : "offline")}</p></div><button id="inventory-edit-player" class="primary" ${Number(row.online) ? "disabled" : ""}>${Number(row.online) ? "Nhân vật đang online" : "Chỉnh hành trang"}</button></div><div class="inventory-summary-grid">${blocks.map(([label, value]) => inventoryBlockSummary(label, value)).join("")}</div></section>`;
    $("#inventory-edit-player")?.addEventListener("click", () => playerStateModule(row.id));
