  const baseDrops = state.dropRows ?? selected.asset.rows.map(row => ({ ...row, itemName:`Vật phẩm #${row.id}`, icon:null }));
  const selectedIndex = Number.isInteger(state.selectedIndex) ? state.selectedIndex : null;
  const pending = data.pending;
  const eventIdLabel = event => event.eventId === null ? "ID legacy/chưa gán" : `event ID ${event.eventId}`;
  const catalog = data.catalog.map(event => `<button class="module-card ${event.key === selected.key ? "active" : ""}" data-event-select="${esc(event.key)}"><p class="eyebrow">${esc(event.kind)}</p><h4>${esc(event.label)}</h4><p>${esc(event.description)}</p><small class="muted">${esc(event.className)} · ${esc(eventIdLabel(event))}</small></button>`).join("");
  const pendingView = pending ? `<section class="card alert-banner"><div class="section-title"><h3>Plan chờ áp dụng ${tag("pending")}</h3><button id="event-discard" class="ghost">Hủy plan</button></div><p><strong>${esc(pending.label)}</strong> · kết thúc ${esc(new Date(pending.endAt).toLocaleString())}</p><p class="muted">Plan chưa đổi event đang chạy. Dừng Java rồi chạy <code>bash run-server.sh</code> để launcher sao lưu config và áp dụng một lần.</p></section>` : `<section class="card"><h3>Chưa có kế hoạch event</h3><p class="muted">Chọn event, điều chỉnh danh sách vật phẩm rơi và lưu plan có xác nhận.</p></section>`;
  const dropBuilder = selected.assetPath ? `<section class="full event-drop-builder"><div class="section-title"><div><h4>Vật phẩm rơi</h4><p class="muted">Chọn vật phẩm từ catalog rồi đặt tỷ lệ rơi. Panel tự lưu cấu trúc nội bộ cho launcher.</p></div><button type="button" id="event-drop-add" class="ghost">Thêm vật phẩm rơi</button></div><div class="event-drop-list">${eventDropRows(baseDrops, selectedIndex)}</div><div class="toolbar"><label>Tìm item reward<input id="event-drop-search-query" placeholder="Ví dụ: lồng đèn" /></label><button type="button" id="event-drop-search" class="ghost" ${selectedIndex === null ? "disabled" : ""}>Tìm item</button></div><div id="event-drop-search-results" class="inventory-empty">${selectedIndex === null ? "Chọn một dòng trước, sau đó tìm item theo tên." : "Tìm catalog để chọn item cho dòng đang đánh dấu."}</div></section>` : `<div class="full"><p class="muted">Drop của event này do Java điều khiển. Panel chỉ preview catalog/điểm và không chỉnh source code.</p></div>`;
  const preview = selected.asset.error ? `<p class="error">${esc(selected.asset.error)}</p>` : selected.asset.rows.length ? `<div class="event-preview-list">${selected.asset.rows.map(row => `<span class="inventory-chip">#${esc(row.id)} · ${esc(row.percent)}%</span>`).join("")}</div>` : `<p class="muted">Event không có bảng drop có thể chỉnh trong panel.</p>`;
  const points = data.unavailable ? `<p class="muted">${esc(data.unavailable)}</p>` : `${table(data.summary, ["event_id","player_count"])}<div style="margin-top:16px">${table(data.rows, ["id","event_id","player_id","player_name","point"])}</div>`;
  const runbook = ["Lưu plan có xác nhận", "Dừng Java game", "Chạy bash run-server.sh để launcher backup và áp dụng plan", "Mở lại panel để kiểm tra event active"].map(step => `<li>${esc(step)}</li>`).join("");
  $("#content").innerHTML = hero("Event Control Center", "Chọn event, quản lý vật phẩm rơi theo từng dòng và lưu pending plan. Panel không hot-switch Java runtime.") + `<section class="grid metric-grid"><article class="card"><div class="metric-label">Event hiện tại</div><div class="metric-value" style="font-size:1.15rem">${esc(data.active.className)}</div><div class="metric-hint">Hết hạn: ${esc(data.active.endAt || "chưa cấu hình")}</div></article><article class="card"><div class="metric-label">Plan pending</div><div class="metric-value">${pending ? esc(pending.label) : "NONE"}</div><div class="metric-hint">Chỉ áp dụng sau restart</div></article><article class="card"><div class="metric-label">Event có drop chỉnh được</div><div class="metric-value">${data.catalog.filter(event => event.assetPath).length}</div><div class="metric-hint">Thiết lập bằng builder trực quan</div></article></section>${pendingView}<section class="card" style="margin-top:16px"><div class="section-title"><h3>Catalog event</h3><span class="muted">${data.catalog.length} cấu hình Java</span></div><div class="module-grid">${catalog}</div></section><section class="split" style="margin-top:16px"><article class="card"><h3>${esc(selected.label)}</h3><p class="muted">${esc(selected.description)}</p><p class="muted"><code>${esc(selected.className)}</code> · ${esc(eventIdLabel(selected))}</p><form id="event-plan-form" class="form-grid"><label>Thời hạn kết thúc<input type="datetime-local" name="endAt" required /></label>${dropBuilder}<button class="primary">Lưu plan event có xác nhận</button></form></article><article class="card"><h3>Preview vật phẩm rơi hiện có</h3>${preview}<details style="margin-top:16px"><summary>Runbook áp dụng an toàn</summary><ol class="runbook-list">${runbook}</ol></details></article></section><section class="card" style="margin-top:16px"><div class="section-title"><h3>Điểm & top event (chỉ đọc)</h3><span class="muted">event_points</span></div>${points}</section>`;
