  const rewardRows = items.map((item, index) => `<article class="gift-reward-card"><div class="item-label">${itemThumb(item.icon, item.itemName, item.itemId)}<div><strong>${esc(item.itemName)}</strong><small>${esc(item.quantity)} cái · ${item.isLock ? "Khóa" : "Không khóa"} · Hạn: ${Number(item.expireDays) ? `${esc(item.expireDays)} ngày` : "Vĩnh viễn"}</small><small>${item.options.length ? `${item.options.length} option` : "Không option"}</small></div></div><button type="button" class="ghost" data-reward-remove="${index}">Bỏ</button></article>`).join("") || `<div class="inventory-empty">Chưa có item. Campaign vẫn có thể cấp tiền tệ.</div>`;
