  const claimRows = data.claims.map(row => `<tr><td>${esc(row.title)}</td><td>${esc(row.player_name || "-")}</td><td>${esc(row.username || "-")}</td><td>${esc(row.claimed_at)}</td></tr>`).join("") || `<tr><td colspan="4" class="muted">Chưa có lượt nhận.</td></tr>`;
